```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, notifier, state_rw};
use wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input received, as approved by the platform team.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {} fetched {}", seconds, fetched);
        let mut notified = false;
        for _ in 0..3 {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
